+  @Test
+  public void testOutputEntryTypes() throws Exception {
+    Artifact missingFile = ActionsTestUtil.createArtifact(outputDir, "missing");
+    Artifact fileWithDir = ActionsTestUtil.createArtifact(outputDir, "file_with_dir");
+    fileWithDir.getPath().createDirectoryAndParents();
+    SpecialArtifact symlink =
+        ActionsTestUtil.createUnresolvedSymlinkArtifact(outputDir, "symlink");
+    symlink.getPath().getParentDirectory().createDirectoryAndParents();
+    symlink.getPath().createSymbolicLink(PathFragment.create("target"));
+    SpecialArtifact symlinkWithFile =
+        ActionsTestUtil.createUnresolvedSymlinkArtifact(outputDir, "symlink_with_file");
+    writeFile(symlinkWithFile, "abc");
+
+    Spawn spawn =
+        defaultSpawnBuilder()
+            .withOutputs(missingFile, fileWithDir, symlink, symlinkWithFile)
+            .build();
+
+    SpawnLogContext context = createSpawnLogContext();
+
+    context.logSpawn(
+        spawn,
+        createInputMetadataProvider(),
+        createInputMap(),
+        fs,
+        defaultTimeout(),
+        defaultSpawnResult());
+
+    context.close();
+
+    HashMap<Integer, ExecLogEntry> entryMap = new HashMap<>();
+    ExecLogEntry.Spawn spawnEntry = null;
+    try (InputStream in = new ZstdInputStream(logPath.getInputStream())) {
+      ExecLogEntry e;
+      while ((e = ExecLogEntry.parseDelimitedFrom(in)) != null) {
+        entryMap.put(e.getId(), e);
+        if (e.hasSpawn()) {
+          spawnEntry = e.getSpawn();
+        }
+      }
+    }
+
+    assertThat(spawnEntry).isNotNull();
+    assertThat(spawnEntry.getOutputsList()).hasSize(4);
+
+    assertThat(spawnEntry.getOutputs(0).getTypeCase())
+        .isEqualTo(ExecLogEntry.Output.TypeCase.MISSING_PATH);
+    assertThat(spawnEntry.getOutputs(0).getMissingPath()).isEqualTo("out/missing");
+
+    assertThat(spawnEntry.getOutputs(1).getTypeCase())
+        .isEqualTo(ExecLogEntry.Output.TypeCase.INVALID_PATH);
+    assertThat(spawnEntry.getOutputs(1).getInvalidPath()).isEqualTo("out/file_with_dir");
+
+    assertThat(spawnEntry.getOutputs(2).getTypeCase())
+        .isEqualTo(ExecLogEntry.Output.TypeCase.FILE_ID);
+    ExecLogEntry.File symlinkEntry =
+        entryMap.get(spawnEntry.getOutputs(2).getFileId()).getFile();
+    assertThat(symlinkEntry.getPath()).isEqualTo("out/symlink");
+    assertThat(symlinkEntry.getSymlinkTargetPath()).isEqualTo("target");
+
+    assertThat(spawnEntry.getOutputs(3).getTypeCase())
+        .isEqualTo(ExecLogEntry.Output.TypeCase.INVALID_PATH);
+    assertThat(spawnEntry.getOutputs(3).getInvalidPath()).isEqualTo("out/symlink_with_file");
+  }
